import zipfile, pickle, struct, io, json, collections

Z = zipfile.ZipFile('/app/model.pth')

class Storage:
    def __init__(self, name, numel):
        self.name = name
        self.numel = numel
        raw = Z.read('simple_mnist/data/' + name)
        self.data = struct.unpack('<%df' % numel, raw[:4 * numel])

class FloatStorage:
    pass

def persistent_load(pid):
    if pid[0] == 'storage':
        return Storage(pid[2], pid[4])
    raise pickle.UnpicklingError(repr(pid))

def _rebuild_tensor_v2(storage, offset, size, stride, requires_grad, backward_hooks, metadata=None):
    def rec(dim, base):
        if dim == len(size):
            return storage.data[base]
        return [rec(dim + 1, base + i * stride[dim]) for i in range(size[dim])]
    return rec(0, offset)

class Unpickler(pickle.Unpickler):
    def find_class(self, mod, name):
        if mod == 'torch._utils' and name == '_rebuild_tensor_v2':
            return _rebuild_tensor_v2
        if mod == 'torch' and name == 'FloatStorage':
            return FloatStorage
        if mod == 'collections' and name == 'OrderedDict':
            return collections.OrderedDict
        raise pickle.UnpicklingError(f'{mod}.{name}')
    def persistent_load(self, pid):
        return persistent_load(pid)

state = Unpickler(io.BytesIO(Z.read('simple_mnist/data.pkl'))).load()
weights = {k: v for k, v in state.items() if k != '_metadata'}
with open('/app/weights.json', 'w') as f:
    json.dump(weights, f, separators=(',', ':'))
    f.write('\n')
print('wrote weights.json')
for k, v in weights.items():
    if isinstance(v[0], list):
        print(k, len(v), 'x', len(v[0]))
    else:
        print(k, len(v))
